beforeExample:
package my.package;

import org.eclipse.core.runtime.Preferences;
import org.eclipse.jdt.core.JavaCore;
// In a real project, org.eclipse.jdt.internal.ui.JavaPlugin would be on the classpath,
// but for this 'before' example, we focus on the old API usage.

// Minimal stubs for compilation context in a self-contained example
class Plugin { public Preferences getPluginPreferences() { return null; } }
class JdtCoreStub { public static Plugin getPlugin() { return new Plugin(); } }

public class MyClass {
    public void method() {
        Preferences prefs = JdtCoreStub.getPlugin().getPluginPreferences();
    }
}

